"""Local harness: build & evaluate plans against cost_model."""
import json, sys, math
sys.path.insert(0, '/workspace/task_file/scripts')
from cost_model import CostModel, HEADS, HIDDEN, align

BUCKET_PATH = '/workspace/task_file/input_data/requests_bucket_{}.jsonl'

def load(b):
    return [json.loads(l) for l in open(BUCKET_PATH.format(b))]

def to_plan(assign, shape_of_batch):
    """assign: list of (rid, batch_id); shape_of_batch: bid->(s,h,hid)"""
    recs=[]
    for rid,bid in assign:
        s,h,hid = shape_of_batch[bid]
        recs.append({'request_id':rid,'batch_id':bid,'shape':{'seq_align':s,'heads_align':h,'hidden_align':hid}})
    return recs

def evaluate(b, assign, shape_of_batch, verbose=True, gran=64):
    reqs = load(b)
    reqd = {r['request_id']: r for r in reqs}
    plan = to_plan(assign, shape_of_batch)
    cm = CostModel(gran)
    m = cm.plan_metrics(reqd, plan)
    # validation
    errs=[]
    ids=[p['request_id'] for p in plan]
    if len(ids)!=len(set(ids)): errs.append('duplicate ids')
    if set(ids)!=set(reqd): errs.append('missing/extra ids')
    by=dict()
    for p in plan: by.setdefault(p['batch_id'],[]).append(p)
    shapes=set()
    for bid,ps in by.items():
        sh=set((p['shape']['seq_align'],p['shape']['heads_align'],p['shape']['hidden_align']) for p in ps)
        if len(sh)!=1: errs.append(f'shape mismatch in {bid}')
        s=ps[0]['shape']['seq_align']
        if s%64!=0: errs.append(f'{bid} seq_align not mult 64')
        for p in ps:
            need=((reqd[p['request_id']]['prompt_len']+63)//64)*64
            if s<need: errs.append(f'{bid} seq_align {s} < need {need}')
        shapes.add(tuple(ps[0]['shape'].values()))
    m['n_batches']=len(by); m['n_shapes']=len(shapes); m['errs']=errs
    if verbose:
        print(f"b{b}: cost={m['cost']:.4e} pad_ratio={m['pad_ratio']:.4f} p95={m['p95_latency_ms']:.4e} seq={m['sequential_timecost']:.4e} batches={m['n_batches']} shapes={m['n_shapes']} errs={errs}")
    return m

THRESH = {1:{'cost':3.0e11,'pad_ratio':0.055,'p95_latency_ms':2.1e6,'sequential_timecost':2.7e8},
          2:{'cost':4.8e10,'pad_ratio':0.15,'p95_latency_ms':2.1e5,'sequential_timecost':3.2e7}}

def check(b,m):
    t=THRESH[b]; ok=True
    for k,v in t.items():
        st = 'OK ' if m[k] < v else 'FAIL'
        if m[k]>=v: ok=False
        print(f"   {st} {k}: {m[k]:.4e} / {v:.4e}")
    return ok
