import json, collections, sys, math
sys.path.insert(0,'/workspace/work'); sys.path.insert(0,'/workspace/task_file/scripts')
from eval_plan import load, evaluate
HID=4096
def align(x,g=64): return ((x+g-1)//g)*g
def sumsq(a,n): return n*a*a + a*n*(n-1) + n*(n-1)*(2*n-1)//6
def sumlin(a,n): return n*a + n*(n-1)//2
def f_cost(s,g): return 1.0*sumsq(s,g) + 2048.0*sumlin(s,g)
def dec_lat(s,g): return 0.0012*sumsq(s,g) + 0.0006*HID*sumlin(s,g)
def pre_lat(S): return 0.002*S*S + 0.0015*S*HID
def seq_cell(S,G): return pre_lat(S)+dec_lat(S,G)+8.0

def solve_banded(reqs, w, lam_pad, pad_budget, OH=1e7):
    """Return list of cells: (Gmax, S_lo_excl, S_hi, g_lo, g_hi)."""
    gmap=collections.defaultdict(lambda: collections.defaultdict(int))
    for r in reqs: gmap[r['gen_len']][align(r['prompt_len'])]+=1
    gvals=sorted(gmap)
    Svals=sorted({align(r['prompt_len']) for r in reqs})
    sidx={s:i for i,s in enumerate(Svals)}
    m=len(gvals); NS=len(Svals)
    dp=[float('inf')]*(m+1); arg=[0]*(m+1); dp[0]=0.0
    band_info={}
    for j in range(m):
        G=gvals[j]
        cnt=[0]*NS; n=0; sumg=0
        best=None; besti=0; bestinfo=None
        for i in range(j,-1,-1):
            for s,c in gmap[gvals[i]].items():
                k=sidx[s]; cnt[k]+=c; n+=c; sumg+=c*gvals[i]
            pad_band=n*G-sumg
            if pad_band>pad_budget: break
            items=[(Svals[k],cnt[k]) for k in range(NS) if cnt[k]>0]
            L=len(items)
            dpp=[0.0]*(L+1); argp=[0]*(L+1); pref=[0]*(L+1)
            for t in range(L): pref[t+1]=pref[t]+items[t][1]
            for b in range(1,L+1):
                Sb=items[b-1][0]; fc=f_cost(Sb,G); extra=OH+w*seq_cell(Sb,G)
                bb=None; bi=0
                for a in range(1,b+1):
                    nn=pref[b]-pref[a-1]
                    val=dpp[a-1]+nn*fc+extra
                    if bb is None or val<bb: bb=val; bi=a
                dpp[b]=bb; argp[b]=bi
            val=dp[i]+dpp[L]+lam_pad*pad_band
            if best is None or val<best:
                best=val; besti=i
                # decode clusters
                clusters=[]; b=L
                while b>0:
                    a=argp[b]
                    s_hi=items[b-1][0]
                    s_lo=items[a-2][0] if a-2>=0 else -1
                    clusters.append((s_lo,s_hi)); b=a-1
                clusters.reverse()
                bestinfo=(i,j,G,clusters)
        if best is None: raise RuntimeError("no band feasible")
        dp[j+1]=best; arg[j+1]=besti; band_info[j]=bestinfo
    cells=[]; j=m
    while j>0:
        i,jj,G,clusters=band_info[j-1]
        for (s_lo,s_hi) in clusters:
            cells.append((G,s_lo,s_hi,gvals[i],gvals[j-1]))
        j=i
    return cells

def cells_to_plan(reqs, cells):
    # assign each request to unique cell (band G range and S range)
    assign=[]; shape_of={}
    maxS=max(align(r['prompt_len']) for r in reqs)
    byid=collections.defaultdict(list)
    for idx,c in enumerate(cells):
        byid[idx]=[]
    for r in reqs:
        s=align(r['prompt_len']); g=r['gen_len']
        for idx,(G,s_lo,s_hi,g_lo,g_hi) in enumerate(cells):
            if g_lo<=g<=g_hi and s_lo<s<=s_hi:
                byid[idx].append(r['request_id']); break
        else:
            raise RuntimeError(f"unassigned req {r}")
    for idx,rids in byid.items():
        if not rids: continue
        bid=f"b-{idx:04d}"
        G,s_lo,s_hi,g_lo,g_hi=cells[idx]
        shape_of[bid]=(maxS,32,4096)
        for rid in rids: assign.append((rid,bid))
    return assign,shape_of

TH={1:{'cost':3.0e11,'pad_ratio':0.055,'p95_latency_ms':2.1e6,'sequential_timecost':2.7e8},
    2:{'cost':4.8e10,'pad_ratio':0.15,'p95_latency_ms':2.1e5,'sequential_timecost':3.2e7}}
def feas(bk,m):
    return (all(m[k]<v for k,v in TH[bk].items()) and not m['errs'])

if __name__=='__main__':
    for bk in (1,2):
        reqs=load(bk); padb=2854 if bk==1 else 3225
        print(f"===== bucket {bk}")
        for w in (0.,50.,100.,200.,400.,600.,1000.):
            for lam in (0.,2000.,20000.,200000.):
                cells=solve_banded(reqs,w,lam,int(padb*0.97))
                assign,shape_of=cells_to_plan(reqs,cells)
                m=evaluate(bk,assign,shape_of,verbose=False)
                print(f" w={w:6.0f} lam={lam:7.0f}: cost={m['cost']:.4e} pad={m['pad_ratio']:.4f} p95={m['p95_latency_ms']:.4e} seq={m['sequential_timecost']:.4e} B={m['n_batches']} errs={len(m['errs'])} {'FEAS' if feas(bk,m) else ''}")
