OUT='/workspace/task_file/output_data/plan_b%d.jsonl'
allshapes=set()
def inhash(p):
    return hashlib.sha256(open(p,'rb').read()).hexdigest()
inp={b:inhash(f'/workspace/task_file/input_data/requests_bucket_{b}.jsonl') for b in (1,2)}

for b in (1,2):
