        recs.append({'request_id':rid,'batch_id':bid,
                     'shape':{'seq_align':s,'heads_align':h,'hidden_align':hid}})
    with open(OUT%b,'w') as f:
        for r in recs: f.write(json.dumps(r)+'\n')
    allshapes |= {tuple(r['shape'].values()) for r in recs}

# ---- independent verification straight from the written files ----
ok_all=True
for b in (1,2):
    reqs=load(b); reqd={r['request_id']:r for r in reqs}
    plan=[json.loads(l) for l in open(OUT%b)]
    errs=[]
    ids=[p['request_id'] for p in plan]
    if len(ids)!=len(reqd): errs.append(f'count {len(ids)} != {len(reqd)}')
    if len(ids)!=len(set(ids)): errs.append('duplicate request_ids')
    if set(ids)!=set(reqd): errs.append('missing/extra request ids')
    by={}
    for p in plan: by.setdefault(p['batch_id'],[]).append(p)
