    passed = all(x<y for x,y in checks.values())
    ok_all &= passed and not errs
    print(f"--- bucket {b}: batches={len(by)} shapes_in_bucket={nsh} errs={errs if errs else 'none'}")
    for k,(x,y) in checks.items():
        print(f"    {'OK  ' if x<y else 'FAIL'} {k:22s} {x:.6e}  (< {y:.1e})")
    print(f"    passed={passed}")

print("unique shapes across both buckets:", len(allshapes), sorted(allshapes))
print("shape budget ok:", len(allshapes)<=8)
print("input files unchanged:", all(inp[b]==inhash(f'/workspace/task_file/input_data/requests_bucket_{b}.jsonl') for b in (1,2)))
